import type { Metadata } from 'next';
import { routeByPath, SITE_URL } from '@/lib/routes';

const ROUTE = '/services/research-impact/simplified-abstract-services/';
const meta = routeByPath.get(ROUTE)!;

export const metadata: Metadata = {
  title: meta.title,
  description: meta.description,
  alternates: { canonical: SITE_URL + ROUTE },
  openGraph: {
    title: meta.title,
    description: meta.description,
    url: SITE_URL + ROUTE,
    type: 'website',
    images: ["https://pubrica.com/share/pubrica-card.jpg"],
  },
};

const schema = [{"@context":"https://schema.org","@type":"Service","name":"Simplified abstract","serviceType":"Research impact service","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/research-impact/simplified-abstract-services/","description":"Your manuscript condensed into the abstract your target journal asks for. The 250 words that decide whether anybody reads the other 6,000.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"How do you keep technical specificity while making it readable?","acceptedAnswer":{"@type":"Answer","text":"By deciding what a reader has to know to judge the study, and writing that in the plainest language it can be written in. The technical terms that carry meaning stay; the ones that are habit go.\n\nThe test we apply is whether a reviewer one field over could state your objective, your design and your main result after one read. If not, the abstract is not finished."}},{"@type":"Question","name":"Can you produce several versions for different targets?","acceptedAnswer":{"@type":"Answer","text":"Yes — journal, grant, repository, conference and lay versions from the same manuscript, each adapted in tone, length and structure.\n\nDifferent word counts are routine: 150, 200 and 250 are the common ones, and what gets cut between them is a judgement about the study rather than a trim of the prose. Ordered together they are quoted together, since the paper only has to be read once."}},{"@type":"Question","name":"Will a systematic review abstract meet PRISMA?","acceptedAnswer":{"@type":"Answer","text":"Yes. The PRISMA 2020 abstract checklist has twelve items — the objective, the eligibility criteria, the information sources, the risk-of-bias method, the synthesis, the results with effect estimates, the limitations and the registration among them.\n\nFor randomised trials the equivalent is CONSORT for abstracts, which is a different seventeen-item list. We apply whichever the study type calls for."}},{"@type":"Question","name":"Can it suit a journal with both clinical and academic readers?","acceptedAnswer":{"@type":"Answer","text":"Yes, and those are the harder ones. Hybrid journals want clinical terminology and statistical precision in the same 250 words, and they want the outcome stated in terms a practising clinician can act on.\n\nWhat that usually means in practice is leading on the outcome and its magnitude rather than on the mechanism, and putting the population and the setting early."}},{"@type":"Question","name":"Will it match the word limit exactly?","acceptedAnswer":{"@type":"Answer","text":"Yes. Word limits are checked against the journal’s own author instructions, including whether headings, citations and the trial registration number count toward the total, which varies.\n\nWhere the journal specifies nothing, we deliver a 200 to 250 word submission-ready abstract in standard academic convention and tell you that is what we have assumed."}},{"@type":"Question","name":"Do you write the abstract from the manuscript, or from the title and conclusion?","acceptedAnswer":{"@type":"Answer","text":"From the manuscript. A subject matter expert reads the full paper, including the methods and the tables, before drafting.\n\nThis is the difference that matters. Abstracts written from the title and the conclusion read plausibly and routinely misstate the design, the comparison or the primary outcome — which is exactly what a reviewer checks first."}},{"@type":"Question","name":"Do you edit the manuscript as well?","acceptedAnswer":{"@type":"Answer","text":"Not as part of this service. This covers the abstract only.\n\nIf the paper itself needs work, manuscript editing and journal formatting are separate services, and ordering them together is usually cheaper and faster than ordering them apart."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Services","item":"https://pubrica.com/services/"},{"@type":"ListItem","position":3,"name":"Research impact","item":"https://pubrica.com/services/research-impact/simplified-abstract-services/"}]}];

